<?php require_once 'includes/auth.php'; require_login(); $q=trim($_GET['q']??'');$status=trim($_GET['status']??'');$sql='SELECT * FROM complaints WHERE user_id=?';$args=[$_SESSION['user']['id']];if($q){$sql.=' AND (description LIKE ? OR location LIKE ? OR category LIKE ?)';$like="%$q%";$args=array_merge($args,[$like,$like,$like]);}if($status){$sql.=' AND status=?';$args[]=$status;}$sql.=' ORDER BY created_at DESC';$st=$pdo->prepare($sql);$st->execute($args);$rows=$st->fetchAll();$page_title='My Complaints';include 'includes/header.php'; ?>
<div class="page-head compact"><div><div class="eyebrow">YOUR REPORTS</div><h1>My complaints</h1><p class="muted">Search and track every issue you've reported.</p></div><a href="submit_complaint.php" class="btn btn-primary">＋ New complaint</a></div><form class="filters"><div class="search-wrap"><span>⌕</span><input name="q" value="<?=e($q)?>" placeholder="Search by issue, category or location..."></div><select name="status"><option value="">All statuses</option><?php foreach(['Pending','Assigned','In Progress','Resolved'] as $s):?><option <?= $status===$s?'selected':''?>><?=e($s)?></option><?php endforeach;?></select><button class="btn btn-secondary">Filter</button><?php if($q||$status):?><a class="btn btn-ghost" href="my_complaints.php">Clear</a><?php endif;?></form><div class="results-label"><?=count($rows)?> complaint<?=count($rows)===1?'':'s'?></div><div class="complaint-list"><?php foreach($rows as $c):?><a class="complaint-card" href="complaint.php?id=<?=$c['id']?>"><div class="category-dot"></div><div class="complaint-main"><div class="complaint-title"><b>#<?=e($c['id'])?> · <?=e($c['description'])?></b><?=status_badge($c['status'])?></div><div class="complaint-meta"><span><?=e($c['category'])?></span><span>•</span><span><?=e($c['location'])?></span><span>•</span><span><?=e(date('d M Y, g:i A',strtotime($c['created_at'])))?></span></div></div><span class="chevron">›</span></a><?php endforeach;?></div><?php if(!$rows):?><div class="empty-state small"><div class="empty-icon">⌕</div><h3>No matching complaints</h3><p>Try another search or clear the filters.</p></div><?php endif;?><?php include 'includes/footer.php'; ?>
